package com.example.starter.torque;

import org.springframework.stereotype.Component;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;

/**
 * 统一时间来源，默认使用 UTC 系统时钟；测试可替换为可控时钟。
 * 工具“当日有效”的日界按 UTC 判定。
 */
@Component
public class ServiceClock {

    private volatile Clock clock = Clock.systemUTC();

    /** 替换底层时钟，仅供测试控制时间使用。 */
    public void setClock(Clock clock) {
        this.clock = clock;
    }

    public Instant now() {
        return clock.instant();
    }

    /** 当前 UTC 日期，用于力矩工具日校验判定。 */
    public LocalDate todayUtc() {
        return clock.instant().atOffset(ZoneOffset.UTC).toLocalDate();
    }
}

package com.example.starter.torque;

/**
 * 工序卡状态机：派工→力矩紧固→自检互检→见证点→放行归档。
 */
public enum CardStatus {
    /** 已派工，紧固未全部完成。 */
    DISPATCHED,
    /** 全部紧固点合格，待自检。 */
    SELF_CHECK,
    /** 自检完成，待互检。 */
    MUTUAL_CHECK,
    /** 互检完成，H 点待见证（无 H 点时不经过此态）。 */
    WITNESS_PENDING,
    /** 见证缺席，转等待中。 */
    WAITING,
    /** 等待满 2 小时已升级。 */
    ESCALATED,
    /** 见证完成，可进入覆盖工序并放行归档。 */
    COVERING,
    /** 终态：已放行归档。 */
    RELEASED,
    /** 终态：同一紧固点返工 2 次后仍超差，整批隔离评审。 */
    QUARANTINED
}

