310	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, ErrorCodes.ILLEGAL_STATE,
311	                    "工序卡已终态 " + status + "，不接受见证");
312	        }
313	        if (List.of(CardStatus.DISPATCHED.name(), CardStatus.SELF_CHECK.name(),
314	                CardStatus.MUTUAL_CHECK.name(), CardStatus.COVERING.name()).contains(status)) {
315	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, ErrorCodes.ILLEGAL_STATE,
316	                    "当前状态 " + status + " 不处理见证");
317	        }
318	
319	        Instant now = clock.now();
320	        boolean justEscalated = false;
321	        Instant waitUntil = null;
322	
323	        // 等待中：恰满 2 小时即判定升级。
324	        if (CardStatus.WAITING.name().equals(status)) {
325	            WitnessEventRow absent = latestEventOfType(card.id(), request.pointCode(), "ABSENT");
326	            waitUntil = absent.eventAt().plus(WITNESS_WAIT);
327	            if (!now.isBefore(waitUntil)) {
328	                repo.insertWitnessEvent(new WitnessEventRow(0L, card.id(), request.pointCode(),
329	                        "ESCALATED", null, now, "见证缺席等待满 2 小时，升级处理"));
330	                repo.updateStatus(card.id(), CardStatus.ESCALATED.name());
331	                status = CardStatus.ESCALATED.name();
332	                justEscalated = true;
333	            }
334	        }
335	
336	        if (request.present()) {
337	            if (request.witness() == null || request.witness().isBlank()) {
338	                throw new ApiException(HttpStatus.BAD_REQUEST, ErrorCodes.BAD_REQUEST,
339	                        "见证到场时 witness 不能为空");
340	            }
341	            Optional<WitnessEventRow> existing = repo.latestWitnessEvent(card.id(), request.pointCode());
342	            if (existing.isPresent() && "WITNESSED".equals(existing.get().eventType())) {
343	                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, ErrorCodes.ILLEGAL_STATE,
344	                        "H 点 " + request.pointCode() + " 已见证完成");
345	            }
346	            repo.insertWitnessEvent(new WitnessEventRow(0L, card.id(), request.pointCode(),
347	                    "WITNESSED", request.witness(), now, null));
348	            if (allHPointsWitnessed(card.id())) {
349	                // H 点未见证不得进入覆盖工序；全部见证完成方可覆盖。
350	                repo.updateStatus(card.id(), CardStatus.COVERING.name());
351	                status = CardStatus.COVERING.name();
352	            }
353	            return new WitnessResult(cardNo, request.pointCode(), "WITNESSED", request.witness(),
354	                    justEscalated, null, now, status);
355	        }
356	
357	        // present=false：提请时缺席转等待；已等待/升级则返回当前判定。
358	        if (CardStatus.WITNESS_PENDING.name().equals(status)) {
359	            repo.insertWitnessEvent(new WitnessEventRow(0L, card.id(), request.pointCode(),
360	                    "ABSENT", null, now, "见证人缺席，转等待"));
361	            repo.updateStatus(card.id(), CardStatus.WAITING.name());
362	            return new WitnessResult(cardNo, request.pointCode(), "ABSENT", null, false,
363	                    now.plus(WITNESS_WAIT), now, CardStatus.WAITING.name());
364	        }
365	
366	        String eventType = justEscalated || CardStatus.ESCALATED.name().equals(status)
367	                ? "ESCALATED" : "ABSENT";
368	        WitnessEventRow reference = repo.latestWitnessEvent(card.id(), request.pointCode()).orElseThrow();
369	        return new WitnessResult(cardNo, request.pointCode(), eventType, null,
370	                CardStatus.ESCALATED.name().equals(status), waitUntil, reference.eventAt(), status);
